package com.jobworker.processing

import com.mongodb.client.MongoClients
import com.mongodb.client.MongoCollection
import com.mongodb.client.MongoDatabase
import org.bson.Document
import org.bson.conversions.Bson
import com.mongodb.client.model.Filters
import java.util.Base64
import java.nio.charset.StandardCharsets
import org.slf4j.LoggerFactory

data class JobMessage(
    val jobId: String,
    val tenantId: String,
    val action: String,
    val payload: Map<String, Any>
)

class QueryBuilder {
    private val logger = LoggerFactory.getLogger(QueryBuilder::class.java)

    fun buildTenantFilter(tenantId: String): Bson {
        return Filters.eq("tenant_id", tenantId)
    }

    fun buildLookupFilter(field: String, value: Any): Bson {
        return Filters.eq(field, value)
    }

    fun buildCompoundFilter(filters: List<Bson>): Bson {
        return Filters.and(filters)
    }
}

class PayloadSanitizer {
    private val ALLOWED_CHARS = Regex("^[a-zA-Z0-9._@\\-]+$")
    private val MAX_LENGTH = 256

    fun sanitizeString(input: String): String {
        val trimmed = input.trim().take(MAX_LENGTH)
        if (!ALLOWED_CHARS.matches(trimmed)) {
            throw IllegalArgumentException("Invalid characters in input: $trimmed")
        }
        return trimmed
    }

    fun sanitizePayload(payload: Map<String, Any>): Map<String, Any> {
        return payload.mapValues { (_, value) ->
            when (value) {
                is String -> sanitizeString(value)
                is Number -> value
                is Boolean -> value
                else -> throw IllegalArgumentException("Unsupported payload type: ${value::class}")
            }
        }
    }
}

class DocumentResolver(private val db: MongoDatabase) {
    private val logger = LoggerFactory.getLogger(DocumentResolver::class.java)
    private val queryBuilder = QueryBuilder()
    private val ALLOWED_FIELDS = setOf("status", "priority", "created_at", "updated_at", "type", "category")

    fun resolveByEncodedQuery(collection: String, encodedQuery: String, tenantId: String): List<Document> {
        val col = db.getCollection(collection)
        val queryDoc = decodeAndParseQuery(encodedQuery)
        val safeFilter = buildSafeFilter(queryDoc)
        val tenantFilter = queryBuilder.buildTenantFilter(tenantId)
        val combinedFilter = queryBuilder.buildCompoundFilter(listOf(tenantFilter, safeFilter))
        logger.info("Executing resolved query on collection=$collection for tenant=$tenantId")
        return col.find(combinedFilter).toList()
    }

    private fun buildSafeFilter(queryDoc: Document): Bson {
        val filters = mutableListOf<Bson>()
        for (key in queryDoc.keys) {
            if (key.startsWith("\$")) {
                throw IllegalArgumentException("Operator keys not allowed in query: $key")
            }
            if (!ALLOWED_FIELDS.contains(key)) {
                throw IllegalArgumentException("Field not in allowlist: $key")
            }
            val value = queryDoc[key]
            if (value is Document && value.keys.any { it.startsWith("\$") }) {
                throw IllegalArgumentException("Operator values not allowed for field: $key")
            }
            filters.add(Filters.eq(key, value))
        }
        if (filters.isEmpty()) {
            throw IllegalArgumentException("Empty query not allowed")
        }
        return queryBuilder.buildCompoundFilter(filters)
    }

    private fun decodeAndParseQuery(encoded: String): Document {
        val decoded = String(Base64.getDecoder().decode(encoded), StandardCharsets.UTF_8)
        return Document.parse(decoded)
    }
}

class JobProcessor(
    private val db: MongoDatabase,
    private val sanitizer: PayloadSanitizer
) {
    private val logger = LoggerFactory.getLogger(JobProcessor::class.java)
    private val queryBuilder = QueryBuilder()
    private val resolver = DocumentResolver(db)
    private val ALLOWED_COLLECTIONS = setOf("orders", "tasks", "events", "notifications")

    fun processJob(message: JobMessage) {
        logger.info("Processing job ${message.jobId} for tenant ${message.tenantId}")

        val tenantId = sanitizer.sanitizeString(message.tenantId)

        when (message.action) {
            "LOOKUP" -> handleLookup(tenantId, message.payload)
            "AGGREGATE" -> handleAggregate(tenantId, message.payload)
            "RESOLVE" -> handleResolve(tenantId, message.payload)
            else -> throw IllegalArgumentException("Unknown action: ${message.action}")
        }
    }

    private fun handleLookup(tenantId: String, payload: Map<String, Any>) {
        val sanitized = sanitizer.sanitizePayload(payload)
        val collection = sanitized["collection"] as? String
            ?: throw IllegalArgumentException("Missing collection")
        validateCollection(collection)
        val field = sanitized["field"] as? String
            ?: throw IllegalArgumentException("Missing field")
        val value = sanitized["value"]
            ?: throw IllegalArgumentException("Missing value")

        val col = db.getCollection(collection)
        val tenantFilter = queryBuilder.buildTenantFilter(tenantId)
        val lookupFilter = queryBuilder.buildLookupFilter(field, value)
        val combined = queryBuilder.buildCompoundFilter(listOf(tenantFilter, lookupFilter))

        val results = col.find(combined).toList()
        logger.info("Lookup returned ${results.size} documents")
    }

    private fun handleAggregate(tenantId: String, payload: Map<String, Any>) {
        val sanitized = sanitizer.sanitizePayload(payload)
        val collection = sanitized["collection"] as? String
            ?: throw IllegalArgumentException("Missing collection")
        validateCollection(collection)

        val col = db.getCollection(collection)
        val matchStage = Document("\$match", Document("tenant_id", tenantId))
        val groupStage = Document("\$group", Document("_id", "\$status")
            .append("count", Document("\$sum", 1)))

        val results = col.aggregate(listOf(matchStage, groupStage)).toList()
        logger.info("Aggregation returned ${results.size} groups")
    }

    private fun handleResolve(tenantId: String, payload: Map<String, Any>) {
        val collection = payload["collection"] as? String
            ?: throw IllegalArgumentException("Missing collection")
        val encodedQuery = payload["query"] as? String
            ?: throw IllegalArgumentException("Missing query")

        val sanitizedCollection = sanitizer.sanitizeString(collection)
        validateCollection(sanitizedCollection)

        // Resolve uses encoded query for complex cross-service lookups
        val results = resolver.resolveByEncodedQuery(sanitizedCollection, encodedQuery, tenantId)
        logger.info("Resolve returned ${results.size} documents")
    }

    private fun validateCollection(name: String) {
        if (!ALLOWED_COLLECTIONS.contains(name)) {
            throw IllegalArgumentException("Collection not allowed: $name")
        }
    }
}

fun main() {
    val mongoUri = System.getenv("MONGO_URI") ?: "mongodb://localhost:27017"
    val dbName = System.getenv("MONGO_DB") ?: "jobworker"
    val client = MongoClients.create(mongoUri)
    val db = client.getDatabase(dbName)
    val sanitizer = PayloadSanitizer()
    val processor = JobProcessor(db, sanitizer)

    // Simulated message consumption loop (in production: Kafka/RabbitMQ consumer)
    val logger = LoggerFactory.getLogger("Main")
    logger.info("Job worker started, waiting for messages...")

    // Example: would be replaced by actual message broker consumption
    Runtime.getRuntime().addShutdownHook(Thread {
        logger.info("Shutting down job worker...")
        client.close()
    })

    Thread.currentThread().join()
}
